const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });

  // 1. Geometry & Time Definitions
  // Define Canada's geometry
  const canada = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Canada'))
    .geometry();

  // Define date ranges
  const startDate_2023 = '2023-01-01';
  const endDate_2023 = '2023-08-03';
  const startDate_2025 = '2025-01-01';
  const endDate_2025 = '2025-08-03';

  const getBurnedArea = async (startDate, endDate, countryGeom, year) => {
    // MODIS Burned Area Collection (MCD64A1.006 is commonly used)
    const collection = ee.ImageCollection('MODIS/061/MCD64A1')
      .filterDate(startDate, endDate)
      .filterBounds(countryGeom);

    const colSize = await collection.size().getInfo();
    if (colSize === 0) {
      console.log(`No images found for ${year} (${startDate} to ${endDate}).`);
      return { area: null, status: 'C1' };
    }

    // Calculate end day of year for filtering BurnDate
    const endDOY = ee.Date(endDate).getRelative('day', 'year').add(1); // +1 because getRelative is 0-indexed

    // Mask for burned pixels within the specified period
    // The 'BurnDate' band is day of year (DOY). 0 means not burned.
    // Convert BurnDate to milliseconds since epoch for comparison with ee.Date objects
    const burnedImages = collection.map(image => {
      const burnDateBand = image.select('BurnDate');
      // Create a mask where BurnDate > 0 and BurnDate <= endDOY
      // And the pixel quality (QA) allows for a confident burn detection.
      // QA band is not directly available in MCD64A1, but 'BurnDate' itself is quality-filtered.
      const burnedMask = burnDateBand.gt(0).and(burnDateBand.lte(endDOY));
      return image.updateMask(burnedMask);
    });

    const maskedColSize = await burnedImages.select('BurnDate').mosaic().mask().reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: countryGeom,
      scale: 500, // MCD64A1 resolution is 500m
      maxPixels: 1e9
    }).get('BurnDate').getInfo();

    if (maskedColSize === 0) {
      console.log(`No valid burned pixels after masking for ${year}.`);
      return { area: null, status: 'C2' };
    }

    // Get the pixel area in square meters for the MODIS resolution
    const pixelArea = ee.Image.pixelArea().mask(burnedImages.select('BurnDate').mosaic().mask());

    // Calculate total burned area by summing up pixel areas where 'BurnDate' is valid.
    // Use the maximum value image to ensure we count each burned pixel once
    // as it can appear in multiple monthly composites.
    const burnedAreaImage = burnedImages.select('BurnDate').max().gt(0); // Any burn in the period
    const totalBurnedArea = burnedAreaImage.multiply(pixelArea).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: countryGeom,
      scale: 500, // MODIS resolution is 500m
      maxPixels: 1e10
    }).get('BurnDate').getInfo();

    return { area: totalBurnedArea, status: 'OK', pixelCount: maskedColSize };
  };

  console.log("Starting analysis for 2023...");
  const result_2023 = await getBurnedArea(startDate_2023, endDate_2023, canada, 2023);
  console.log("Starting analysis for 2025...");
  const result_2025 = await getBurnedArea(startDate_2025, endDate_2025, canada, 2025);

  if (result_2023.status !== 'OK') {
    console.log(result_2023.status);
    return;
  }
  if (result_2025.status !== 'OK') {
    console.log(result_2025.status);
    return;
  }

  const burnedArea2023_km2 = result_2023.area / 1e6; // Convert m^2 to km^2
  const burnedArea2025_km2 = result_2025.area / 1e6;

  if (burnedArea2023_km2 === null || burnedArea2025_km2 === null || isNaN(burnedArea2023_km2) || isNaN(burnedArea2025_km2)) {
    console.log("Calculation failed: Burned area is null or NaN.");
    console.log("C3");
    return;
  }

  console.log(`2023 Burned Area (Jan-Aug 3): ${burnedArea2023_km2.toFixed(2)} km² (Pixels: ${result_2023.pixelCount})`);
  console.log(`2025 Burned Area (Jan-Aug 3): ${burnedArea2025_km2.toFixed(2)} km² (Pixels: ${result_2025.pixelCount})`);

  if (burnedArea2025_km2 > burnedArea2023_km2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

initEE();
